def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] not in (0, 5)]
    if len(markers) != 2:
        return out
    # The two marker colors are copied into a four-quadrant checker pattern
    # inside the 5-frame. Their spatial order determines which diagonal leads.
    r0, c0 = 3, 3
    a, b = markers[0][2], markers[1][2]
    if markers[0][0] == markers[1][0]:
        # Top and bottom marker pairs orient the diagonal oppositely.
        reverse = (markers[0][1] > markers[1][1]) if markers[0][0] < 5 else (markers[0][1] < markers[1][1])
    elif markers[0][1] == markers[1][1]:
        # Same column above/below: upper marker gets the opposite diagonal.
        reverse = markers[0][0] > markers[1][0]
    elif markers[0][0] == markers[1][0] and markers[0][0] > 7:
        # Markers below the frame: right marker is NW/SE.
        reverse = True
    else:
        reverse = False
    for r in range(r0, r0 + 4):
        for c in range(c0, c0 + 4):
            same_diagonal = (r < r0 + 2) == (c < c0 + 2)
            out[r][c] = (b if same_diagonal else a) if reverse else (a if same_diagonal else b)
    return out
